insert into public.translation_strings (key, value_en, value_fi) values ('home.storyP1', 'Kuopio Bites started as a neighbourhood grilli on Jalkasenkatu and grew into something rarer: a place where a wood-fired pizza and a proper Karachi biryani come out of the same steaming kitchen.', 'Kuopio Bites alkoi kortteligrillinä Jalkasenkadulla ja kasvoi harvinaiseksi paikaksi: puu-uunipizza ja kunnon Karachi-biryani samasta höyryävästä keittiöstä.');
insert into public.translation_strings (key, value_en, value_fi) values ('home.storyP2', 'Family recipes, fresh Finnish ingredients, and portions that respect your appetite.', 'Perhereseptit, tuoreet suomalaiset raaka-aineet ja annokset, jotka kunnioittavat ruokahalua.');
