insert into public.translation_strings (key, value_en, value_fi) values ('dining.kicker', 'tervetuloa — welcome', 'tervetuloa');
insert into public.translation_strings (key, value_en, value_fi) values ('dining.title', 'Dining at Kuopio Bites', 'Ruokailu Kuopio Bitesissa');
insert into public.translation_strings (key, value_en, value_fi) values ('dining.lead', 'Casual dine-in in the heart of Kuopio: warm light, steam over the pass, and the smell of wood-fired pizza meeting biryani masala.', 'Rentouttava illallinen Kuopion ytimessä: lämmin valo, höyryä passin yllä ja puu-uunipizzan sekä biryani-masalan tuoksu.');
insert into public.translation_strings (key, value_en, value_fi) values ('dining.seats', '40 seats inside, plus a sunny terrace in summer. Family tables, high chairs and a quiet corner for laptop lunches.', '40 paikkaa sisällä ja aurinkoinen terassi kesällä. Perhepöydät, syöttötuolit ja rauhallinen nurkka eväsläppärille.');
insert into public.translation_strings (key, value_en, value_fi) values ('dining.amb', 'Half grilli, half South Asian kitchen — order a Perhe pizza and a Karachi biryani for the table and share the best of both.', 'Puoliksi grilli, puoliksi eteläaasialainen keittiö — tilaa pöytään Perhe-pizza ja Karachi-biryani ja jaa molempien parhaat.');
insert into public.translation_strings (key, value_en, value_fi) values ('dining.hoursNote', 'Kitchen serves the full menu during opening hours. No reservation needed for small groups — but booking guarantees your table.', 'Keittiö tarjoilee koko ruokalistan aukioloaikoina. Pieniä seurueita ilman varausta — varaus takaa pöydän.');
