insert into public.translation_strings (key, value_en, value_fi) values ('acct.track', 'Track →', 'Seuraa →');
insert into public.translation_strings (key, value_en, value_fi) values ('about.kicker', 'since day one, with love', 'alusta asti, rakkaudella');
insert into public.translation_strings (key, value_en, value_fi) values ('about.title', 'A grilli with two hearts', 'Grilli, jolla on kaksi sydäntä');
insert into public.translation_strings (key, value_en, value_fi) values ('about.sub', 'Finnish grilli comfort and South Asian soul food, side by side on Jalkasenkatu.', 'Suomalaista grilli-lohtua ja eteläaasialaista soul foodia vieretysten Jalkasenkadulla.');
insert into public.translation_strings (key, value_en, value_fi) values ('about.p1', 'Kuopio Bites began with a simple craving: real Karachi biryani on a Kuopio winter night, and a proper wood-fired pizza for the kids. Instead of choosing, we built one kitchen that does both — seriously.', 'Kuopio Bites alkoi yksinkertaisesta himosta: kunnon Karachi-biryani kuopiolaiseen talviyöhön ja kunnon puu-uunipizza lapsille. Emme valinneet — rakensimme keittiön, joka tekee molemmat.');
insert into public.translation_strings (key, value_en, value_fi) values ('about.p2', 'Our pizza dough rests for two days. Our biryani masala is ground in-house from a family recipe. The kebab is carved the Finnish way, the halwa is stirred the slow way, and the wings are fried until they shatter.', 'Pizzataikina lepää kaksi päivää. Biryani-masala jauhetaan perhereseptistä. Kebab veistetään suomalaisittain, halwa kypsyy hitaasti ja wingsit paistetaan rapeiksi.');
insert into public.translation_strings (key, value_en, value_fi) values ('about.p3', 'Whether you come for a lunch biryani, a family Perhe-pizza night, or a grilli plate after sauna — the steam over our door means you''re welcome.', 'Tulitpa lounas-biryaniin, perheen Perhe-pizzailtaan tai grilli-lautaseen saunan jälkeen — höyry oven yllä tarkoittaa: olet tervetullut.');
