insert into public.shop_settings (id, paused, pause_message, hours, delivery_fee, min_order, radius_km, vat_rate, preorder, blocked_dates, blocked_slots, announcement, extra) values (true, false, 'Keittiömme pitää lyhyen tauon — palaamme pian!', '{"0":{"open":"12:00","close":"21:00"},"1":{"open":"10:00","close":"21:00"},"2":{"open":"10:00","close":"21:00"},"3":{"open":"10:00","close":"21:00"},"4":{"open":"10:00","close":"21:00"},"5":{"open":"10:00","close":"22:00"},"6":{"open":"11:00","close":"22:00"}}'::jsonb, 2.5, 15, 6, 0.135, '{"enabled":true,"cutoffDay":6,"cutoffTime":"18:00","slots":["10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00"],"capacity":40,"noteEn":"Order by Saturday 18:00 for Sunday pickup.","noteFi":"Tilaa viimeistään lauantaina klo 18.00 sunnuntain noutoa varten."}'::jsonb, '{}'::date[], '{}'::text[], '{"enabled":false,"text":""}'::jsonb, '{"headerLogo":"round","hideUnavailable":false,"platforms":{"wolt":"https://wolt.com/en/cities/kuopio","uberEats":"https://www.ubereats.com/fi/city/kuopio"}}'::jsonb) on conflict (id) do update set paused=excluded.paused, pause_message=excluded.pause_message, hours=excluded.hours, delivery_fee=excluded.delivery_fee, min_order=excluded.min_order, radius_km=excluded.radius_km, vat_rate=excluded.vat_rate, preorder=excluded.preorder, blocked_dates=excluded.blocked_dates, blocked_slots=excluded.blocked_slots, announcement=excluded.announcement, extra=excluded.extra;
